    'camera.prop.exposure_auto.title': "Belichtung automatisch",
    'camera.prop.exposure_auto.text': "Die Kamera regelt die Belichtungszeit selbst nach. Ausschalten nur, wenn das Licht immer gleich ist – sonst werden Bilder bei Sonne und Wolken unterschiedlich.",
    'camera.prop.exposure_value.title': "Belichtungszeit",
    'camera.prop.exposure_value.text': "Wie lange der Sensor Licht sammelt. Länger heißt heller, aber auch mehr Bewegungsunschärfe – bei einer Rodelbahn der entscheidende Kompromiss.",
    'camera.prop.exposure_auto_reference.title': "Ziel-Helligkeit",
    'camera.prop.exposure_auto_reference.text': "Worauf die automatische Belichtung hinregelt. Höher heißt hellere Bilder. Der wirksamste Regler, solange die Automatik an ist.",
    'camera.prop.gain_auto.title': "Verstärkung automatisch",
    'camera.prop.gain_auto.text': "Hebt das Signal an, wenn zu wenig Licht da ist. Kostet Bildrauschen.",
    'camera.prop.gain_auto_max_value.title': "Verstärkung höchstens",
    'camera.prop.gain_auto_max_value.text': "Die Obergrenze für die Verstärkung. Niedriger heißt sauberere, aber dunklere Bilder bei schlechtem Licht.",
    'camera.prop.saturation_value.title': "Sättigung",
    'camera.prop.saturation_value.text': "Wie kräftig die Farben sind. 100 ist neutral.",
    'camera.prop.gamma_value.title': "Gamma",
    'camera.prop.gamma_value.text': "Verteilt die Helligkeit ungleichmäßig: hebt Schatten an, ohne die Lichter auszubrennen. Kleiner als 1 heißt heller.",
    'camera.prop.brightness_value.title': "Helligkeit",
    'camera.prop.brightness_value.text': "Hebt oder senkt das ganze Bild gleichmäßig – ohne Einfluss auf die Schärfe.",
    'camera.prop.contrast_value.title': "Kontrast",
    'camera.prop.contrast_value.text': "Der Abstand zwischen hell und dunkel. Zu viel frisst Zeichnung in Schatten und Himmel.",
    'camera.prop.hue_value.title': "Farbton",
    'camera.prop.hue_value.text': "Dreht alle Farben im Kreis. Zum Ausgleichen eines Farbstichs, nicht zum Gestalten.",
    'camera.prop.whitebalance_auto.title': "Weißabgleich automatisch",
    'camera.prop.whitebalance_auto.text': "Gleicht die Farbe des Lichts aus, damit Weiß weiß bleibt – morgens anders als mittags.",
    'camera.prop.highlight_reduction_enable.title': "Spitzlichter dämpfen",
    'camera.prop.highlight_reduction_enable.text': "Rettet Zeichnung in ausgefressenen hellen Stellen – Himmel, Schnee, Sonnenreflexe auf dem Helm. Bei Gegenlicht der interessanteste Schalter.",
    'camera.prop.tone_mapping_enable.title': "Tone Mapping",
    'camera.prop.tone_mapping_enable.text': "Holt Schatten und Lichter gleichzeitig zurück. Macht kontrastreiche Bilder ausgewogener, kann aber flau wirken.",
