    'tour.overview.title': "Übersicht",
    'tour.overview.benefit': "Hier bekommst du den schnellsten Gesamtüberblick über deinen Park, ohne dich erst durch einzelne Bereiche zu klicken.",
    'tour.overview.actions': "Du siehst die wichtigsten Tages- und Monatszahlen, die Umsatzkurve und aktuelle operative Hinweise auf einen Blick.",
    'tour.overview.kpis': "Wichtig sind hier vor allem Umsatz heute, verkaufte Fotos, Fotopapier, Monatswerte und aktuelle Hinweise.",
    'tour.revenue.title': "Umsatz",
    'tour.revenue.benefit': "Diese Seite hilft dir, Einnahmen genauer zu verstehen und Trends schneller zu erkennen.",
    'tour.revenue.actions': "Du kannst Tagesverläufe, Monatsentwicklung und Verkaufsleistung nach Zeitraum oder Datenbasis prüfen.",
    'tour.revenue.kpis': "Hier zählen Umsatzsummen, verkaufte Fotos, Conversion und der Verlauf der Umsatzlinie.",
    'tour.purchases.title': "Käufe",
    'tour.purchases.benefit': "Hier siehst du jede einzelne Transaktion und kannst schnell nachvollziehen, was am Automaten verkauft wurde.",
    'tour.purchases.actions': "Du kannst Käufe filtern, durchsuchen, exportieren und einzelne Vorgänge nach Datum, Betrag oder Quelle prüfen.",
    'tour.purchases.kpis': "Wichtig sind Kaufzeitpunkt, Zahlungsart, Status, Quelle und der jeweilige Einzelumsatz.",
    'tour.photos.title': "Fotos",
    'tour.photos.benefit': "Diese Seite ist dein operativer Blick auf die erzeugten Bilder und zeigt dir sofort, ob der Fotozufluss passt.",
    'tour.photos.actions': "Du kannst nach Bildnummer, Datum oder Quelle suchen, Vorschauen öffnen und Volumen nach Tagen vergleichen.",
    'tour.photos.kpis': "Wichtig sind hier Fotoanzahl, aktuelle Uploads, Verteilung nach Tagen und die sichtbare Vorschau einzelner Bilder.",
    'tour.leads.title': "CRM",
    'tour.leads.benefit': "Hier erkennst du, welche Gäste ihre Bilder digital freischalten oder nach dem Besuch noch mit dem Bild interagieren.",
    'tour.leads.actions': "Du kannst Kontakte filtern, nach Land segmentieren, einzelne Einträge löschen und die Weltkarte sowie Einlösezeiten auswerten.",
    'tour.leads.kpis': "Wichtig sind Kontakte gesamt, Marketing-Opt-ins, Länder, Zeit zwischen Kauf und Einlösung und die detaillierte Standortkarte.",
    'tour.personalization.title': "Personalisierung",
    'tour.personalization.benefit': "Hier gestaltest du Overlays und Kampagnen, damit Fotos markengerecht und passend zum Park ausgespielt werden.",
    'tour.personalization.actions': "Du kannst Overlays hochladen, im Builder anpassen, Kampagnen anlegen und Ebenen mit Vorschau kombinieren.",
    'tour.personalization.kpis': "Wichtig sind hier eher die aktiven Overlays, die Kampagnenlogik und die direkte Vorschau auf dem neuesten Bild.",
    'tour.support.title': "Support",
    'tour.support.benefit': "Hier laufen technische oder organisatorische Rückfragen zusammen, damit du Probleme schneller lösen kannst.",
    'tour.support.actions': "Du kannst Tickets lesen, beantworten, archivieren und neue Fälle anlegen, wenn etwas im Betrieb auffällt.",
    'tour.support.kpis': "Wichtig sind offene Tickets, Prioritäten, Status und die letzten Antworten unseres Support-Teams.",
    'tour.health.title': "Systemzustand",
    'tour.health.benefit': "Diese Seite zeigt dir, ob Kameras, Uploads und Maschinen stabil laufen oder Aufmerksamkeit brauchen.",
    'tour.health.actions': "Du kannst Maschinenstatus, letzte Signale, Fehlerbilder und Ausfälle prüfen und direkt Auffälligkeiten erkennen.",
    'tour.health.kpis': "Wichtig sind Online-Status, letzte Aktivität, Warnungen, Upload-Signale und technische Störungen.",
    'tour.settings.title': "Einstellungen",
    'tour.settings.benefit': "Hier steuerst du die wichtigsten Grundparameter deines Dashboards und deines Parkbetriebs.",
    'tour.settings.actions': "Du kannst Sprache, Bildpreis, Benachrichtigungen, Öffnungszeiten, Saisonzeiten und Organisationsdaten verwalten.",
