    'camera.prop.exposure_auto.title': "Automatic exposure",
    'camera.prop.exposure_auto.text': "The camera adjusts the exposure time by itself. Only switch it off if the light is always the same – otherwise images will differ between sun and clouds.",
    'camera.prop.exposure_value.title': "Exposure time",
    'camera.prop.exposure_value.text': "How long the sensor collects light. Longer means brighter, but also more motion blur – on a toboggan run this is the key trade-off.",
    'camera.prop.exposure_auto_reference.title': "Target brightness",
    'camera.prop.exposure_auto_reference.text': "What the automatic exposure aims for. Higher means brighter images. The most effective control while automatic mode is on.",
    'camera.prop.gain_auto.title': "Automatic gain",
    'camera.prop.gain_auto.text': "Boosts the signal when there is too little light. Costs image noise.",
    'camera.prop.gain_auto_max_value.title': "Maximum gain",
    'camera.prop.gain_auto_max_value.text': "The upper limit for the gain. Lower means cleaner but darker images in poor light.",
    'camera.prop.saturation_value.title': "Saturation",
    'camera.prop.saturation_value.text': "How strong the colours are. 100 is neutral.",
    'camera.prop.gamma_value.title': "Gamma",
    'camera.prop.gamma_value.text': "Distributes brightness unevenly: lifts shadows without blowing out the highlights. Less than 1 means brighter.",
    'camera.prop.brightness_value.title': "Brightness",
    'camera.prop.brightness_value.text': "Raises or lowers the whole image evenly – without affecting sharpness.",
    'camera.prop.contrast_value.title': "Contrast",
    'camera.prop.contrast_value.text': "The gap between light and dark. Too much eats detail in shadows and sky.",
    'camera.prop.hue_value.title': "Hue",
    'camera.prop.hue_value.text': "Rotates all colours around the colour wheel. For correcting a colour cast, not for creative looks.",
    'camera.prop.whitebalance_auto.title': "Automatic white balance",
    'camera.prop.whitebalance_auto.text': "Compensates for the colour of the light so white stays white – different in the morning than at noon.",
    'camera.prop.highlight_reduction_enable.title': "Reduce highlights",
    'camera.prop.highlight_reduction_enable.text': "Recovers detail in blown-out bright areas – sky, snow, sun reflections on the helmet. The most interesting switch in backlight.",
    'camera.prop.tone_mapping_enable.title': "Tone mapping",
    'camera.prop.tone_mapping_enable.text': "Brings back shadows and highlights at the same time. Balances high-contrast images, but can look flat.",
    'camera.prop.sharpness_value.title': "Sharpness",
    'camera.prop.sharpness_value.text': "Emphasises edges after capture. Too much creates harsh edges and amplifies noise. Cannot be previewed here.",
    'camera.prop.denoise_value.title': "Noise reduction",
