    'camera.prop.exposure_auto.title': "Exposición automática",
    'camera.prop.exposure_auto.text': "La cámara ajusta sola el tiempo de exposición. Desactívala solo si la luz es siempre igual; de lo contrario, las imágenes variarán entre sol y nubes.",
    'camera.prop.exposure_value.title': "Tiempo de exposición",
    'camera.prop.exposure_value.text': "Cuánto tiempo capta luz el sensor. Más tiempo significa más brillo, pero también más desenfoque de movimiento; en una pista de trineos es el compromiso clave.",
    'camera.prop.exposure_auto_reference.title': "Brillo objetivo",
    'camera.prop.exposure_auto_reference.text': "Hacia qué valor regula la exposición automática. Más alto significa imágenes más claras. El control más eficaz mientras el modo automático está activo.",
    'camera.prop.gain_auto.title': "Ganancia automática",
    'camera.prop.gain_auto.text': "Amplifica la señal cuando hay poca luz. Cuesta ruido de imagen.",
    'camera.prop.gain_auto_max_value.title': "Ganancia máxima",
    'camera.prop.gain_auto_max_value.text': "El límite superior de la ganancia. Más bajo significa imágenes más limpias pero más oscuras con poca luz.",
    'camera.prop.saturation_value.title': "Saturación",
    'camera.prop.saturation_value.text': "Qué tan intensos son los colores. 100 es neutro.",
    'camera.prop.gamma_value.title': "Gamma",
    'camera.prop.gamma_value.text': "Distribuye el brillo de forma desigual: aclara las sombras sin quemar las luces. Menos de 1 significa más claro.",
    'camera.prop.brightness_value.title': "Brillo",
    'camera.prop.brightness_value.text': "Sube o baja toda la imagen por igual, sin afectar a la nitidez.",
    'camera.prop.contrast_value.title': "Contraste",
    'camera.prop.contrast_value.text': "La diferencia entre claro y oscuro. Demasiado hace perder detalle en sombras y cielo.",
    'camera.prop.hue_value.title': "Tono",
    'camera.prop.hue_value.text': "Gira todos los colores en el círculo cromático. Sirve para corregir una dominante de color, no para dar estilo.",
    'camera.prop.whitebalance_auto.title': "Balance de blancos automático",
    'camera.prop.whitebalance_auto.text': "Compensa el color de la luz para que el blanco siga siendo blanco; por la mañana es distinto que al mediodía.",
    'camera.prop.highlight_reduction_enable.title': "Reducir las altas luces",
    'camera.prop.highlight_reduction_enable.text': "Recupera detalle en zonas claras quemadas: cielo, nieve, reflejos del sol en el casco. El interruptor más interesante a contraluz.",
    'camera.prop.tone_mapping_enable.title': "Mapeo tonal",
    'camera.prop.tone_mapping_enable.text': "Recupera sombras y luces a la vez. Equilibra las imágenes de mucho contraste, pero puede verse plano.",
    'camera.prop.sharpness_value.title': "Nitidez",
    'camera.prop.sharpness_value.text': "Resalta los bordes tras la captura. Demasiado crea bordes duros y aumenta el ruido. Aquí no se puede previsualizar.",
    'camera.prop.denoise_value.title': "Reducción de ruido",
