    'camera.prop.exposure_auto.title': "Esposizione automatica",
    'camera.prop.exposure_auto.text': "La fotocamera regola da sola il tempo di esposizione. Disattivala solo se la luce è sempre uguale, altrimenti le immagini cambiano tra sole e nuvole.",
    'camera.prop.exposure_value.title': "Tempo di esposizione",
    'camera.prop.exposure_value.text': "Per quanto tempo il sensore raccoglie luce. Più lungo significa più luminoso, ma anche più mosso: su una pista di slittino è il compromesso decisivo.",
    'camera.prop.exposure_auto_reference.title': "Luminosità target",
    'camera.prop.exposure_auto_reference.text': "Il valore a cui punta l’esposizione automatica. Più alto significa immagini più chiare. Il controllo più efficace finché l’automatico è attivo.",
    'camera.prop.gain_auto.title': "Guadagno automatico",
    'camera.prop.gain_auto.text': "Amplifica il segnale quando c’è poca luce. Costa rumore d’immagine.",
    'camera.prop.gain_auto_max_value.title': "Guadagno massimo",
    'camera.prop.gain_auto_max_value.text': "Il limite superiore del guadagno. Più basso significa immagini più pulite ma più scure con poca luce.",
    'camera.prop.saturation_value.title': "Saturazione",
    'camera.prop.saturation_value.text': "Quanto sono intensi i colori. 100 è neutro.",
    'camera.prop.gamma_value.title': "Gamma",
    'camera.prop.gamma_value.text': "Distribuisce la luminosità in modo non uniforme: schiarisce le ombre senza bruciare le luci. Meno di 1 significa più chiaro.",
    'camera.prop.brightness_value.title': "Luminosità",
    'camera.prop.brightness_value.text': "Alza o abbassa l’intera immagine in modo uniforme, senza influire sulla nitidezza.",
    'camera.prop.contrast_value.title': "Contrasto",
    'camera.prop.contrast_value.text': "La distanza tra chiaro e scuro. Troppo contrasto fa perdere dettaglio in ombre e cielo.",
    'camera.prop.hue_value.title': "Tonalità",
    'camera.prop.hue_value.text': "Ruota tutti i colori sul cerchio cromatico. Serve a correggere una dominante di colore, non a dare uno stile.",
    'camera.prop.whitebalance_auto.title': "Bilanciamento del bianco automatico",
    'camera.prop.whitebalance_auto.text': "Compensa il colore della luce affinché il bianco resti bianco: al mattino è diverso che a mezzogiorno.",
    'camera.prop.highlight_reduction_enable.title': "Attenua le alte luci",
    'camera.prop.highlight_reduction_enable.text': "Recupera dettaglio nelle zone chiare bruciate: cielo, neve, riflessi del sole sul casco. L’interruttore più utile in controluce.",
    'camera.prop.tone_mapping_enable.title': "Tone mapping",
    'camera.prop.tone_mapping_enable.text': "Recupera ombre e luci allo stesso tempo. Bilancia le immagini molto contrastate, ma può sembrare piatto.",
    'camera.prop.sharpness_value.title': "Nitidezza",
